{"source": "def settle(charges, slots):
    weights = {}
    caps = {}
    allocations = dict.fromkeys(charges, 0)
    for identifier, value in charges.items():
        if isinstance(value, int):
            weights[identifier] = value
            caps[identifier] = None
        else:
            weights[identifier] = value['weight']
            caps[identifier] = value['cap']
    remaining = slots
    while remaining:
        eligible = [identifier for identifier in charges
                    if weights[identifier] > 0 and
                    (caps[identifier] is None or allocations[identifier] < caps[identifier])]
        if not eligible:
            break
        total = sum(weights[identifier] for identifier in eligible)
        proposals = {}
        remainders = {}
        for identifier in eligible:
            proposals[identifier], remainders[identifier] = divmod(remaining * weights[identifier], total)
        extra = remaining - sum(proposals.values())
        order = sorted(eligible, key=lambda identifier: (-remainders[identifier], identifier))
        for identifier in order[:extra]:
            proposals[identifier] += 1
        for identifier in eligible:
            grant = proposals[identifier]
            if caps[identifier] is not None:
                grant = min(grant, caps[identifier] - allocations[identifier])
            allocations[identifier] += grant
            remaining -= grant
    return allocations
